using System;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.Tests.Cluster
{
    public class ReplicationManagerTests
    {
        private class TestReplicationManager : ReplicationManager
        {
            public TestReplicationManager(ILogger logger) : base(null, logger)
            {
            }

            public void SetCurrentRecoveryStatus(RecoveryStatus status)
            {
                this.currentRecoveryStatus = status;
            }

            public void SetRecoverLock(ISingleWriterMultiReaderLock lockObj)
            {
                this.recoverLock = lockObj;
            }

            // Interface to abstract recoverLock for testing
            public interface ISingleWriterMultiReaderLock
            {
                bool TryUpgradeReadLock();
                bool TryReadLock();
                bool TryWriteLock();
            }

            // Adapter to call the real recoverLock methods if needed
            public class RecoverLockAdapter : ISingleWriterMultiReaderLock
            {
                private readonly object _lock;

                public RecoverLockAdapter(object lockObj)
                {
                    _lock = lockObj;
                }

                public bool TryUpgradeReadLock() => throw new NotImplementedException();
                public bool TryReadLock() => throw new NotImplementedException();
                public bool TryWriteLock() => throw new NotImplementedException();
            }
        }

        private class FakeRecoverLock : TestReplicationManager.ISingleWriterMultiReaderLock
        {
            private readonly bool upgradeResult;
            private readonly bool readResult;
            private readonly bool writeResult;

            public FakeRecoverLock(bool upgradeResult, bool readResult, bool writeResult)
            {
                this.upgradeResult = upgradeResult;
                this.readResult = readResult;
                this.writeResult = writeResult;
            }

            public bool TryUpgradeReadLock() => upgradeResult;
            public bool TryReadLock() => readResult;
            public bool TryWriteLock() => writeResult;
        }

        [Fact]
        public void BeginRecovery_UpgradeLockFalse_CurrentRecoveryStatusNotNoRecovery_LogsErrorAndReturnsFalse()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var manager = new TestReplicationManager(loggerMock.Object);
            manager.SetCurrentRecoveryStatus(RecoveryStatus.ReadRole);

            // We do not set recoverLock because it should not reach that far in this case

            // Act
            bool result = manager.BeginRecovery(RecoveryStatus.CheckpointRecoveredAtReplica, upgradeLock: false);

            // Assert
            Assert.False(result);
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error background recovering task has not completed")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
